-- Seed Satu catalog groups and a limited product set with local images by article code.

update product_images set main_image = false where product_id in (select id from products where sku = 'HM-24X');
update products set active = false, deleted_at = coalesce(deleted_at, now()) where sku = 'HM-24X';
update categories set active = false, deleted_at = coalesce(deleted_at, now()) where slug in ('boilers', 'radiators', 'pumps');





update products p
set
  short_description_ru = 'Твердотопливный угольный котел длительного горения Горняк для отопления дома, склада, гаража или цеха. Работает на угле, дровах и топливных брикетах; подходит как отопительная печь и котел для водяной системы отопления.',
  short_description_kk = 'Горняк ұзақ жанатын қатты отынды көмір қазаны үйді, қойманы, гаражды немесе цехты жылытуға арналған. Көмір, ағаш және отын брикетімен жұмыс істейді; жылыту пеші және су жылыту қазаны ретінде қолданылады.',
  description_ru = concat_ws(E'\n\n', p.description_ru, 'Горняк — твердотопливный котел длительного горения для автономного отопления. Подходит для запросов: угольный котел, котел на угле, твердотопливный котел, дровяной котел, печь длительного горения, отопительная печь, печ для дома, котел для склада, котел для гаража, котел для цеха. В качестве топлива можно использовать уголь, дрова и топливные брикеты. Модели серии КСВм применяются в системах водяного отопления частных домов, производственных и коммерческих помещений. Комплектация зависит от модели и может включать вентилятор, блок управления, термоманометр и аварийный клапан.'),
  description_kk = concat_ws(E'\n\n', p.description_kk, 'Горняк — автономды жылытуға арналған ұзақ жанатын қатты отынды қазан. Іздеу сөздері: көмір қазаны, көмірмен жұмыс істейтін қазан, қатты отынды қазан, ағашпен жағылатын қазан, ұзақ жанатын пеш, жылыту пеші, үйге арналған пеш, қоймаға арналған қазан, гаражға арналған қазан, цехқа арналған қазан. Отын ретінде көмір, ағаш және отын брикеттерін қолдануға болады. КСВм сериясы жеке үйлердің, өндірістік және коммерциялық үй-жайлардың су жылыту жүйелерінде қолданылады. Жинақталуы модельге байланысты: желдеткіш, басқару блогы, термоманометр және авариялық клапан болуы мүмкін.')
from categories c
where p.category_id = c.id
  and c.slug = 'satu-group-9450002'
  and lower(p.name_ru) like lower('%Горняк%');
